import{b as a,O as t,g as s,j as o}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"使用ssh命令传输文件","description":"","frontmatter":{"tags":["工具","SSH"]},"headers":[],"relativePath":"blog/tools/scp-file-transfer/index.md","filePath":"个人博客/工具篇/2.使用ssh命令传输文件.md","lastUpdated":1781623812000}'),d={name:"blog/tools/scp-file-transfer/index.md"};function p(i,e,n,c,r,l){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="使用ssh命令传输文件" tabindex="-1">使用ssh命令传输文件 <a class="header-anchor" href="#使用ssh命令传输文件" aria-label="Permalink to &quot;使用ssh命令传输文件&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>以前一直在 Windows 下用 SSH Secure Shell 连接远程服务器，它自带了一个可视化的文件传输工具，跟 FTP 差不多。</p><p>但是它也存在一个缺陷——不支持编码的选择，遇到 UTF-8 就自动乱码了。另外 macOS 下也没有这个工具。</p><p>在 Mac 下我用终端登录上去之后，想传个文件上去就犯愁了，难不成要开个 FTP？</p><p>搜了一下，果然有直接的命令行工具，名字叫 <strong>SCP</strong>（Secure Copy）。</p><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><h3 id="_1-上传本地文件到服务器" tabindex="-1">1. 上传本地文件到服务器 <a class="header-anchor" href="#_1-上传本地文件到服务器" aria-label="Permalink to &quot;1. 上传本地文件到服务器&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp /path/filename username@servername:/path/</span></span></code></pre></div><p>例如把本机 <code>/var/www/</code> 目录下的 <code>test.php</code> 文件上传到 <code>192.168.0.101</code> 这台服务器上的 <code>/var/www/</code> 目录中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp /var/www/test.php root@192.168.0.101:/var/www/</span></span></code></pre></div><h3 id="_2-从服务器下载文件" tabindex="-1">2. 从服务器下载文件 <a class="header-anchor" href="#_2-从服务器下载文件" aria-label="Permalink to &quot;2. 从服务器下载文件&quot;">​</a></h3><p>下载文件我们经常使用 <code>wget</code>，但是如果没有 HTTP 服务，如何从服务器上下载文件呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp username@servername:/path/filename /本地目录/</span></span></code></pre></div><p>例如把 <code>192.168.0.101</code> 上的 <code>/var/www/test.txt</code> 文件下载到本机 <code>/var/www/</code> 目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp root@192.168.0.101:/var/www/test.txt /var/www/</span></span></code></pre></div><h3 id="_3-从服务器下载整个目录" tabindex="-1">3. 从服务器下载整个目录 <a class="header-anchor" href="#_3-从服务器下载整个目录" aria-label="Permalink to &quot;3. 从服务器下载整个目录&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp -r username@servername:/远程目录/ /本地目录/</span></span></code></pre></div><p>例如把服务器上的 <code>/var/www/test</code> 目录下载到本机 <code>/var/www/</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp -r root@192.168.0.101:/var/www/test /var/www/</span></span></code></pre></div><h3 id="_4-上传目录到服务器" tabindex="-1">4. 上传目录到服务器 <a class="header-anchor" href="#_4-上传目录到服务器" aria-label="Permalink to &quot;4. 上传目录到服务器&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp -r local_dir username@servername:remote_dir</span></span></code></pre></div><p>例如把当前目录下的 <code>test</code> 目录上传到服务器的 <code>/var/www/</code> 目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp -r test root@192.168.0.101:/var/www/</span></span></code></pre></div><h2 id="常用参数" tabindex="-1">常用参数 <a class="header-anchor" href="#常用参数" aria-label="Permalink to &quot;常用参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>-r</code></td><td>递归复制整个目录</td><td><code>scp -r ./dist root@server:/var/www/</code></td></tr><tr><td><code>-P</code></td><td>指定 SSH 端口（默认 22）</td><td><code>scp -P 2222 file root@server:/path/</code></td></tr><tr><td><code>-p</code></td><td>保留文件修改时间和权限</td><td><code>scp -p file root@server:/path/</code></td></tr><tr><td><code>-C</code></td><td>传输时压缩，慢网络下能提速</td><td><code>scp -C largefile root@server:/path/</code></td></tr><tr><td><code>-v</code></td><td>输出详细调试信息</td><td><code>scp -v file root@server:/path/</code></td></tr><tr><td><code>-q</code></td><td>安静模式，不显示进度条</td><td><code>scp -q file root@server:/path/</code></td></tr></tbody></table><blockquote><p>⚠️ 注意区分：<code>-P</code>（大写）指定端口，<code>-p</code>（小写）保留文件属性，搞混了会报错。</p></blockquote><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>1. 报 <code>Permission denied</code></strong></p><p>目标目录没有写入权限，先 SSH 上去确认：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh root@192.168.0.101</span></span>
<span class="line"><span>ls -la /var/www/</span></span></code></pre></div><p><strong>2. 端口不是 22 怎么传？</strong></p><p>用 <code>-P</code>（大写）指定：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp -P 2222 file.txt root@192.168.0.101:/path/</span></span></code></pre></div><p><strong>3. 传输速度太慢怎么办？</strong></p><p>加 <code>-C</code> 压缩传输；大文件或大量文件建议换 <code>rsync</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rsync -avz ./dist/ root@192.168.0.101:/var/www/</span></span></code></pre></div><p><strong>4. 一次传多个文件</strong></p><p>多个源路径空格隔开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp file1.txt file2.txt root@192.168.0.101:/path/</span></span></code></pre></div><h2 id="原文链接" tabindex="-1">原文链接 <a class="header-anchor" href="#原文链接" aria-label="Permalink to &quot;原文链接&quot;">​</a></h2><p><a href="https://www.cnblogs.com/kaffeetrinken/p/9260316.html" target="_blank" rel="noreferrer">SSH 远程上传本地文件至服务器</a></p>`,42)])])}const b=a(d,[["render",p]]);export{u as __pageData,b as default};
